<template><section class="cut-selection" aria-label="裁片选择与打印"><InlineActivity v-if="previewWorking" :label="zh?'正在生成打印预览…':localize('Creating print preview…')"/><div v-if="advanced" class="cut-actions"><button :disabled="store.busy||!project?.pieces.length" @click="bundle('export')">{{zh?'导出裁片 ZIP':localize('Export cuts ZIP')}}</button><button :disabled="store.busy" @click="bundle('import')">{{zh?'导入裁片 ZIP':localize('Import cuts ZIP')}}</button></div><p>{{zh?'默认选择全部裁片，可按需取消。左侧预览当前单片，打印保持毫米原尺寸。':localize('All patterns are selected by default; deselect any you do not need. The left previews one piece; printing preserves actual millimetres.')}}</p><input v-model="search" :placeholder="zh?'搜索裁片':localize('Search patterns')" :aria-label="zh?'搜索裁片':localize('Search patterns')"><div class="select-all"><label class="check-label"><input type="checkbox" :checked="allSelected" @change="toggleAll">{{zh?'全选当前列表':localize('Select all shown')}}</label><span>{{chosen.length}} / {{project?.pieces.length}}</span></div><div class="cut-list"><div v-for="p in pieces" :key="p.id" :class="['cut-row',{active:selectedId===p.id}]"><input type="checkbox" v-model="chosen" :value="p.id" :aria-label="(zh?'打印选择 ':localize('Print selection '))+p.name"><button class="piece-row" @click="emit('select',p.id)"><svg :viewBox="box(p)"><path :d="piecePath(p)" :fill="p.color" fill-rule="evenodd"/></svg><div><strong>{{p.name}}</strong><small>{{p.cutQty}}× · {{p.color}}</small></div></button></div></div><label v-if="warnings.length" class="check-label"><input v-model="ack" type="checkbox">{{zh?'已检查并确认当前制造警告':localize('Reviewed current manufacturing warnings')}} · {{warnings.length}}</label><small v-if="issues.some(i=>i.severity==='error')" class="cut-error">{{zh?'存在未解决的几何、花纹或接缝问题，请在检查与记录中处理后打印。':localize('Resolve geometry, marking or seam errors in Checks before printing.')}}</small><div class="cut-actions" :class="{simplePreview:!advanced}"><button :disabled="store.busy||previewBusy||actionBlocked" @click="showPreview(actionSingle)">{{actionSingle?(zh?'单片分页拼接预览':localize('Single-piece page preview')):(zh?'选中裁片总览':localize('Selected cuts overview'))}}</button><button v-if="advanced" :disabled="store.busy||previewBusy||!chosen.length||batchBlocked" @click="showPreview(false)">{{zh?'选中裁片总览':localize('Selected cuts overview')}}</button></div><div class="cut-actions" :class="{simple:!advanced}"><button :disabled="store.busy||actionBlocked" @click="output(actionSingle,'print')">{{actionSingle?(zh?'打印当前单片':localize('Print current piece')):(zh?'打印选中裁片':localize('Print selected cuts'))}}</button><button v-if="advanced" :disabled="store.busy||!chosen.length||batchBlocked" @click="output(false,'print')">{{zh?'打印选中裁片':localize('Print selected cuts')}} · {{chosen.length}}</button><button :disabled="store.busy||actionBlocked" @click="output(actionSingle,'pdf')">{{actionSingle?(zh?'单片 PDF':localize('Single-piece PDF')):(zh?'选中裁片 PDF':localize('Selected cuts PDF'))}}</button><button v-if="advanced" :disabled="store.busy||!chosen.length||batchBlocked" @click="output(false,'pdf')">{{zh?'选中裁片 PDF':localize('Selected cuts PDF')}}</button></div><BatchPrintPreview v-if="overview" :overview="overview" :language="language" :busy="previewBusy" :pieces="project?.pieces??[]" @close="closeOverview" @piece="showPreviewPiece"/><PrintPreview v-if="preview" :preview="preview" :language="language" :busy="store.busy" @close="closePreview" @output="(format,pages)=>output(true,format,pages,preview?.pieceIds)"/></section></template>

<script setup lang="ts">
import {localize} from './localization';
import InlineActivity from './InlineActivity.vue';
import {useDelayedActivity} from './modules/useDelayedActivity';

import PrintPreview from './PrintPreview.vue';
import BatchPrintPreview from './BatchPrintPreview.vue';
import {computed,inject,ref,shallowRef,watch,onBeforeUnmount} from 'vue';
import {useSession} from './store';
import {materialIssues} from '../../../packages/manufacturing/material';
import {outputSeamIssues} from '../../../packages/manufacturing/seams';
import {outputBudgetIssues} from '../../../packages/manufacturing/output-limits';
import {piecePath,pointBounds} from '../../../packages/pattern/edit';
import type {Paper,Piece,PrintPreview as PreviewData,PatternOverview} from '../../../packages/schema/index';
const advanced=inject('advancedMode',ref(false));
const props=defineProps<{language:'zh'|'en';selectedId:string;paper:Paper}>(),emit=defineEmits<{select:[id:string]}>(),store=useSession(),zh=computed(()=>props.language==='zh');
const overview=shallowRef<PatternOverview>(),preview=shallowRef<PreviewData>(),previewBusy=ref(false);let previewGeneration=0,disposed=false;
const previewWorking=useDelayedActivity(()=>previewBusy.value);
function cancelPreviewWait(){previewGeneration++;previewBusy.value=false;}
function closePreview(){cancelPreviewWait();preview.value=undefined;}
function closeOverview(){closePreview();overview.value=undefined;}
onBeforeUnmount(()=>{disposed=true;closeOverview();});
const chosen=shallowRef<string[]>([]),search=ref(''),ack=ref(false),project=computed(()=>store.data.project);
const pieces=computed(()=>project.value?.pieces.filter(p=>p.name.toLowerCase().includes(search.value.toLowerCase()))??[]);
watch(()=>[project.value?.id,project.value?.pieces.map(piece=>piece.id)??[]] as const,([id,ids],previous)=>{if(!previous||id!==previous[0])chosen.value=[...ids];else{const oldIds=new Set(previous[1]),selected=new Set(chosen.value);chosen.value=ids.filter(pieceId=>selected.has(pieceId)||!oldIds.has(pieceId));}ack.value=false;},{immediate:true});
const allSelected=computed(()=>{const selected=new Set(chosen.value);return !!pieces.value.length&&pieces.value.every(p=>selected.has(p.id));});
function toggleAll(){const ids=new Set(chosen.value),remove=allSelected.value;for(const p of pieces.value)if(remove)ids.delete(p.id);else ids.add(p.id);chosen.value=[...ids];}
function issuesFor(ids:string[]){const selected=new Set(ids),geometry=store.data.geometry.filter(g=>selected.has(g.id)),issues=[...geometry.flatMap(g=>g.issues),...(project.value?[...materialIssues(project.value).filter(i=>selected.has(i.entityId)),...outputSeamIssues(project.value,store.data.geometry,ids),...outputBudgetIssues({...project.value,pieces:project.value.pieces.filter(p=>selected.has(p.id))},geometry)]:[])];return [...new Map(issues.map(i=>[i.ruleId,i])).values()];}
const issues=computed(()=>issuesFor([...chosen.value,props.selectedId]));
const warnings=computed(()=>issues.value.filter(i=>i.severity==='warning'));
const blocked=(ids:string[])=>{const scoped=issuesFor(ids);return scoped.some(i=>i.severity==='error')||scoped.some(i=>i.severity==='warning')&&!ack.value;};
const singleBlocked=computed(()=>blocked([props.selectedId])),batchBlocked=computed(()=>blocked(chosen.value));
const actionSingle=computed(()=>advanced.value||!chosen.value.length),actionBlocked=computed(()=>actionSingle.value?!props.selectedId||singleBlocked.value:batchBlocked.value);
watch([()=>project.value?.id,()=>project.value?.revision,()=>props.selectedId,()=>chosen.value.join(',')],()=>{ack.value=false;});
function box(p:Piece){const b=pointBounds(p.nodes);return `${b.minX-5} ${-b.maxY-5} ${b.maxX-b.minX+10} ${b.maxY-b.minY+10}`;}
async function output(single:boolean,format:'print'|'pdf'|'svg',pageNumbers?:number[],previewIds?:string[]){const p=project.value,ids=previewIds?[...previewIds]:(single?[props.selectedId]:[...chosen.value]);if(p&&ids.length)await store.run(()=>window.fpcad.patternOutput(p.id,p.revision,ids,format,JSON.parse(JSON.stringify(props.paper)),ack.value?issuesFor(ids).filter(i=>i.severity==='warning').map(i=>i.ruleId):[],pageNumbers));}
watch([()=>project.value?.id,()=>project.value?.revision,()=>JSON.stringify(props.paper)],closeOverview);
async function showPreview(single:boolean){const p=project.value,ids=single?[props.selectedId]:[...chosen.value];if(disposed||!p||!ids.length)return;const own=++previewGeneration,projectId=p.id,revision=p.revision,paperKey=JSON.stringify(props.paper),reportError=store.captureError(),current=()=>!disposed&&own===previewGeneration&&project.value?.id===projectId&&project.value.revision===revision&&JSON.stringify(props.paper)===paperKey;reportError('');previewBusy.value=true;try{const response=await window.fpcad[ids.length>1?'patternOverview':'patternPreview'](p.id,p.revision,ids,JSON.parse(paperKey),ack.value?warnings.value.map(i=>i.ruleId):[]);if(!current())return;if(response.ok){preview.value=response.printPreview;overview.value=response.patternOverview;}else reportError(response.error.code);}catch{if(current())reportError('CONNECTION_ERROR');}finally{if(own===previewGeneration)previewBusy.value=false;}}
async function showPreviewPiece(id:string){const p=project.value;if(disposed||!p)return;const own=++previewGeneration,projectId=p.id,revision=p.revision,paperKey=JSON.stringify(props.paper),reportError=store.captureError(),current=()=>!disposed&&own===previewGeneration&&project.value?.id===projectId&&project.value.revision===revision&&JSON.stringify(props.paper)===paperKey;previewBusy.value=true;try{const response=await window.fpcad.patternPreview(p.id,p.revision,[id],JSON.parse(paperKey),ack.value?issuesFor([id]).filter(i=>i.severity==='warning').map(i=>i.ruleId):[]);if(!current())return;if(response.ok)preview.value=response.printPreview;else reportError(response.error.code);}catch{if(current())reportError('CONNECTION_ERROR');}finally{if(own===previewGeneration)previewBusy.value=false;}}
async function bundle(action:'import'|'export'){const p=project.value;if(p)await store.run(()=>window.fpcad.patternBundle(p.id,p.revision,action));}
</script>

<style scoped>.cut-selection{padding:16px;border-bottom:1px solid var(--border)}.cut-actions{display:grid;grid-template-columns:1fr 1fr;gap:7px}.cut-actions+.cut-actions{margin-top:8px}.cut-actions.simplePreview{grid-template-columns:1fr}.cut-selection p{color:var(--accent);font-size:11px;line-height:1.8}.select-all{display:flex;justify-content:space-between;align-items:center;margin:12px 0;font-size:11px}.cut-list{max-height:230px;overflow:auto}.cut-row{display:flex;align-items:center;gap:5px;border:1px solid transparent;border-radius:4px}.cut-row.active{border-color:var(--accent)}.cut-row .piece-row{flex:1;background:transparent;margin:0;padding:7px;min-width:0;display:flex}.cut-row svg{width:40px;height:40px;background:var(--canvas);flex-shrink:0}.cut-row strong{font-size:11px;overflow-wrap:anywhere}.cut-row small{font-size:10px}.cut-row input{width:auto;flex-shrink:0}.cut-selection>.check-label{margin:12px 0;font-size:11px}.cut-error{display:block;color:var(--warning);margin:8px 0}</style>
